package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class ProperFractionProductSupplyTest {
 @Test public void properProductsAndWholeDivisionsHaveExactValuesAndRequiredForm(){Checker check=new Checker();int mul=0,div=0;for(int b=2;b<=12;b++)for(int a=1;a<b;a++){for(int d=2;d<=12;d++)for(int c=1;c<d;c++){Question q=ProperFractionProductSupply.make("fracMul",a,b,c,d);assertEquals(Rational.of((long)a*c,(long)b*d),Expression.number(q.answers[0]));assertEquals("reduced",q.kind);assertNotNull(FractionWork.original(q));assertTrue(check.check(q,List.of(),List.of(q.answers[0])).correct());Rational answer=Expression.number(q.answers[0]);assertFalse(check.check(q,List.of(),List.of(answer.n.multiply(java.math.BigInteger.TWO)+"/"+answer.d.multiply(java.math.BigInteger.TWO))).correct());mul++;}for(int whole=1;whole<=12;whole++){Question q=ProperFractionProductSupply.make("fracDivInt",a,b,whole,1);assertEquals(Rational.of(a,(long)b*whole),Expression.number(q.answers[0]));assertTrue(check.check(q,List.of(),List.of(q.answers[0])).correct());div++;}}assertEquals(4356,mul);assertEquals(792,div);}
 @Test public void reusedProductHelpAndWrongPartComeFromPublicOperands(){for(String id:List.of("fracMul","fracDivInt")){Question original=ProperFractionProductSupply.make(id,2,3,2,id.equals("fracMul")?5:1),q=new Question(id,original.prompt,"poison","999");q.kind=original.kind;HelpPlan h=HelpPlan.forQuestion(q);assertEquals(id.equals("fracMul")?9:11,h.size());assertFalse(h.canTransfer());assertTrue(h.step(0).accepts("2"));assertTrue(h.step(1).accepts("3"));assertTrue(h.step(h.size()-2).accepts(id.equals("fracMul")?"4":"1"));assertTrue(h.step(h.size()-1).accepts(id.equals("fracMul")?"15":"3"));assertEquals(1,FractionInput.errorPart(q,id.equals("fracMul")?"5/15":"2/3"));assertEquals(2,FractionInput.errorPart(q,id.equals("fracMul")?"4/16":"1/4"));}}
 @Test public void reviewedYearSixPlacementsReuseFourExistingTypesWithFreshConditions(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();for(String id:List.of("fracMul","fracDivInt","fracMixedAdd","fracMixedSub")){assertTrue(pack.inGrade(id,6));Generator g=new Generator(new Random(90));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(id,recent,false,GlobalCurriculum.limits(pack.id,id,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertNotNull(q.studyGuide);assertFalse(HelpPlan.forQuestion(q).canTransfer());assertTrue(new Checker().check(q,List.of(),List.of(q.answers[0])).correct());}if(id.startsWith("fracMixed"))assertFalse(pack.inGrade(id,5));}assertFalse(ProperFractionProductSupply.supports("fracMul",CurriculumLimits.NONE));}
}
